          tasks.push_back(task);
        }
      }
    }

    current_group.push_back(seg);
    current_doc_count += doc_count;
    current_actual_doc_count += actual_doc_count;
  }

  if (current_group.size() > 0) {
    SegmentTask::Ptr task;
    if (current_group.size() == 1 && !rebuild) {
